import{$ as e,A as t,B as n,V as r}from"./chunks/framework.Civ1omIV.js";var i=JSON.parse(`{"title":"Clash 与 mihomo、Clash Verge Rev、FlClash、Clash Nyanpasu、ClashMi、OpenClash 的兼容性","description":"从 Clash Verge Rev、FlClash、Clash Nyanpasu、ClashMi、OpenClash、ShellCrash 等 mihomo 客户端迁移到 Clash iOS 的完整兼容说明。","frontmatter":{"title":"Clash 与 mihomo、Clash Verge Rev、FlClash、Clash Nyanpasu、ClashMi、OpenClash 的兼容性","description":"从 Clash Verge Rev、FlClash、Clash Nyanpasu、ClashMi、OpenClash、ShellCrash 等 mihomo 客户端迁移到 Clash iOS 的完整兼容说明。","head":[["meta",{"name":"keywords","content":"mihomo iOS,Clash Verge Rev iOS,FlClash订阅,Clash Nyanpasu配置,ClashMi配置,OpenClash订阅,ShellCrash配置"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"FAQPage\\",\\"mainEntity\\":[{\\"@type\\":\\"Question\\",\\"name\\":\\"Clash 兼容哪些 mihomo 客户端的配置？\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"标准 mihomo YAML 配置或返回 mihomo YAML 的订阅都可以直接导入 Clash，包括 Clash Verge Rev、FlClash、Clash Nyanpasu、ClashMi、OpenClash、ShellCrash 等客户端所使用的 mihomo 配置。\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Clash Verge Rev 的订阅可以用于 Clash iOS 吗？\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"可以。将同一个 mihomo 订阅 URL 添加到 Clash；面板提供多种格式时，可切换订阅 User-Agent 选择 Clash / mihomo 输出。\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"如何把 OpenClash 配置用于 Clash iOS？\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"直接导入标准 mihomo YAML，并在 iOS 上使用 Clash 的规则与系统设置建立对应体验；OpenWrt 插件设置继续由路由器管理。\\"}}]}"]]},"headers":[],"relativePath":"zh/guide/compatibility/mihomo.md","filePath":"zh/guide/compatibility/mihomo.md","lastUpdated":1785318168000}`),a={name:`zh/guide/compatibility/mihomo.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="clash-与-mihomo-客户端全兼容" tabindex="-1">Clash 与 mihomo 客户端全兼容 <a class="header-anchor" href="#clash-与-mihomo-客户端全兼容" aria-label="Permalink to “Clash 与 mihomo 客户端全兼容”">​</a></h1><p>标准 mihomo YAML 配置，或能够返回 mihomo YAML 的订阅，都可以直接导入 Clash。节点、策略组、规则、Provider 与受支持的配置字段会继续使用，免去逐个添加节点的步骤。</p><p>这里的“全兼容”指 mihomo 配置与订阅兼容。界面偏好、系统代理、TUN 与备份等平台设置，可以在 Clash iOS 中按自己的使用习惯重新配置。</p><h2 id="常见-mihomo-客户端" tabindex="-1">常见 mihomo 客户端 <a class="header-anchor" href="#常见-mihomo-客户端" aria-label="Permalink to “常见 mihomo 客户端”">​</a></h2><p>以下是社区中较常见的代表：</p><table tabindex="0"><thead><tr><th>客户端</th><th>常见平台</th><th>迁移到 Clash</th></tr></thead><tbody><tr><td><a href="https://github.com/clash-verge-rev/clash-verge-rev" target="_blank" rel="noreferrer">Clash Verge Rev</a></td><td>Windows、macOS、Linux</td><td>导入原 mihomo YAML 或添加同一个订阅</td></tr><tr><td><a href="https://github.com/chen08209/FlClash" target="_blank" rel="noreferrer">FlClash</a></td><td>Windows、macOS、Linux、Android</td><td>导入原 mihomo YAML 或添加同一个订阅</td></tr><tr><td><a href="https://github.com/libnyanpasu/clash-nyanpasu" target="_blank" rel="noreferrer">Clash Nyanpasu</a></td><td>Windows、macOS、Linux</td><td>导入原 mihomo YAML 或添加同一个订阅</td></tr><tr><td><a href="https://github.com/KaringX/clashmi" target="_blank" rel="noreferrer">ClashMi</a></td><td>iOS、macOS、Android、Windows、Linux</td><td>导入原 mihomo YAML 或添加同一个订阅</td></tr><tr><td><a href="https://github.com/vernesong/OpenClash" target="_blank" rel="noreferrer">OpenClash</a></td><td>OpenWrt</td><td>导入标准 mihomo YAML；插件设置继续由 OpenWrt 管理</td></tr><tr><td><a href="https://github.com/juewuy/ShellCrash" target="_blank" rel="noreferrer">ShellCrash</a></td><td>路由器与 Shell 环境</td><td>导入标准 mihomo YAML；安装与服务设置继续由原环境管理</td></tr></tbody></table><p>更多项目可查看 mihomo 官方文档整理的<a href="https://wiki.metacubex.one/startup/client/client/" target="_blank" rel="noreferrer">第三方工具与客户端列表</a>。</p><h2 id="可以直接带走什么" tabindex="-1">可以直接带走什么？ <a class="header-anchor" href="#可以直接带走什么" aria-label="Permalink to “可以直接带走什么？”">​</a></h2><ul><li>mihomo YAML 配置文件；</li><li>返回 mihomo YAML 的订阅地址；</li><li>节点与代理 Provider；</li><li>策略组与健康检查配置；</li><li>路由规则与 Rule Provider；</li><li>DNS 与受支持的长尾字段。</li></ul><h2 id="平台设置如何衔接" tabindex="-1">平台设置如何衔接 <a class="header-anchor" href="#平台设置如何衔接" aria-label="Permalink to “平台设置如何衔接”">​</a></h2><p>节点、策略组和规则跟随 mihomo YAML 一起迁移；界面主题、窗口布局、快捷键、系统代理、TUN、自动启动、WebDAV 备份和路由器插件等平台设置，则继续由各自平台管理，并可在 Clash iOS 中选择对应体验。</p><p>如果原客户端使用 Merge、Mixin、覆写或脚本动态生成最终配置，请先导出生成后的标准 mihomo YAML，或直接使用原始订阅地址。</p><h2 id="最省事的迁移方式" tabindex="-1">最省事的迁移方式 <a class="header-anchor" href="#最省事的迁移方式" aria-label="Permalink to “最省事的迁移方式”">​</a></h2><ol><li>在原客户端中找到正在使用的订阅 URL。</li><li>在 Clash 中添加该 URL。</li><li>订阅面板提供多种格式时，切换订阅 User-Agent，选择 Clash / mihomo 输出。</li><li>更新配置，确认策略组、规则和节点已经出现。</li><li>测试延迟，选择节点并连接。</li></ol><h2 id="apple-平台差异" tabindex="-1">Apple 平台差异 <a class="header-anchor" href="#apple-平台差异" aria-label="Permalink to “Apple 平台差异”">​</a></h2><p>iPhone 与 iPad 使用 Apple 的 Packet Tunnel 网络层能力。可以把桌面端按进程、按应用的分流意图转换为域名、IP、Rule Set 等规则；路由器接口、透明代理与防火墙设置继续由路由器管理。</p><p>返回<a href="/clash.md/zh/guide/compatibility">兼容性总览</a>。</p>`,17)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};